from .schema import Lesson


LESSONS = [
Lesson("01-model", 1, "مسئلهٔ یادگیری", "چه چیزی در یک مدل تغییر می‌کند؟",
"یک تابع آشنا، یک عدد قابل تنظیم و معیاری برای اینکه بفهمیم تنظیم تازه بهتر شده است.",
"""<p>برای صفحهٔ مقاله‌های یک سایت، می‌خواهیم کنار هر متن زمان تقریبی خواندنش را نشان دهیم. برنامه تعداد بندها را می‌داند، اما هنوز نمی‌داند خواندن متن چند دقیقه طول می‌کشد. برای شروع فقط سه مشاهدهٔ ساختگی داریم؛ این عددها برای تمرین‌اند، نه اندازه‌گیری واقعی سرعت مطالعه.</p>
<table><thead><tr><th>متن</th><th>تعداد بندها</th><th>زمان خواندن، به دقیقه</th></tr></thead><tbody><tr><td>الف</td><td>۱</td><td>۲</td></tr><tr><td>ب</td><td>۲</td><td>۴</td></tr><tr><td>پ</td><td>۳</td><td>۶</td></tr></tbody></table>
<p>یک راه ساده این است که تعداد بندها را در عددی ثابت ضرب کنیم. ضریب ۱، زمان‌های ۱، ۲ و ۳ دقیقه را می‌دهد؛ ضریب ۲، زمان‌های ۲، ۴ و ۶ دقیقه را؛ و ضریب ۳، زمان‌های ۳، ۶ و ۹ دقیقه را. می‌توانید همین محاسبه را با یک تابع Python بنویسید. مسئلهٔ تازه این است: ضریب تابع را چطور با کمک مشاهده‌ها انتخاب کنیم و از کجا بفهمیم انتخابمان بهتر شده است؟</p>
<p><dfn>Model (مدل)</dfn> تابعی است که از ورودی، خروجی می‌سازد. در مثال ما <code>prediction = w * x</code> است. <dfn>Parameter (پارامتر)</dfn> عدد قابل تنظیمِ داخل مدل است؛ اینجا فقط w. <dfn>Prediction (پیش‌بینی)</dfn> خروجیِ حدس‌زده‌شدهٔ مدل است و <dfn>Target (هدف)</dfn> پاسخی است که برای مقایسه در اختیار داریم. هدف را مدل تولید نمی‌کند.</p>
<p>در این نام‌گذاری، x تعداد بندها و w ضریبِ «دقیقه به‌ازای هر بند» است. پاسخ مدل و زمان مشاهده‌شده هر دو واحد دقیقه دارند، پس می‌توانیم اختلافشان را حساب کنیم. برای مقایسهٔ ضریب‌ها، اختلاف پیش‌بینی و هدف را برای هر سه متن مربع می‌کنیم و میانگین می‌گیریم.</p>
<div class="math">prediction = wx<br>loss = [(w×1−2)² + (w×2−4)² + (w×3−6)²] / 3</div>
<p><dfn>Loss (زیان؛ عدد سنجش بدی پیش‌بینی)</dfn> می‌گوید پاسخ مدل با هدف چقدر ناسازگار است. معیار همین مثال <dfn>Mean squared error یا MSE (میانگین مربع خطا)</dfn> نام دارد. مربع‌کردن اجازه نمی‌دهد خطای مثبت یک نمونه، خطای منفی نمونهٔ دیگر را پنهان کند. در این مثال عدد کوچک‌تر بهتر است؛ بعداً برای پیش‌بینی متن، معیار مناسب دیگری می‌سازیم.</p>
<p><dfn>Training (آموزش)</dfn> یعنی با استفاده از مشاهده‌ها و زیان، پارامترها را تغییر دهیم. <dfn>Inference (استفاده از مدل با وزن‌های ثابت)</dfn> یعنی پارامترها را ثابت نگه داریم و ورودی بدهیم. ماشین‌حساب هم خروجی می‌سازد؛ تفاوت اصلی اینجا در چگونگی انتخاب w است، نه در ظاهر خروجی.</p>
<p>نام پروژهٔ همراه کتاب Mini-GPT است: ادامه‌دهندهٔ کوچکی که قدم‌به‌قدم می‌سازیم. معنای GPT را هنگام رسیدن به معماری آن باز می‌کنیم. فعلاً قرارداد مهم این است: داده وارد می‌شود، مدل پیش‌بینی می‌کند، زیان سنجیده می‌شود و پارامتر تغییر می‌کند.</p>""",
"بدون نگاه به کد مرجع، تابع زیان را بنویسید. wهای ۰، ۱، ۲ و ۳ را مقایسه کنید. سپس با بهترین w برای ورودی ۴ پیش‌بینی بسازید و بنویسید کدام بخش نتیجه مشاهده است و کدام بخش فرض.",
"زیان‌ها به‌ترتیب 18.6667، 4.6667، 0 و 4.6667 هستند. با w=2، پیش‌بینی ورودی ۴ برابر ۸ می‌شود. این خروجی را در داده ندیده‌ایم؛ اعتبارش به ادامه‌داشتن رابطهٔ فرضی بستگی دارد. سه نقطه، قانون جهان را اثبات نمی‌کنند.",
"اگر هدف‌ها را عوض کنیم اما w را ثابت نگه داریم، پیش‌بینی عوض می‌شود یا زیان؟ هر دو را برای یک نمونه حساب کنید.",
"در Mini-GPT ورودی و معیار زیان عوض می‌شوند و به‌جای یک w، جدول‌هایی از عدد داریم. چرخهٔ داده، پیش‌بینی، زیان و اصلاح همان است.",
code="""data = [(1, 2), (2, 4), (3, 6)]

def loss(w):
    squared_errors = [(w*x - target)**2 for x, target in data]
    return sum(squared_errors) / len(data)

for w in [0, 1, 2, 3]:
    print(w, round(loss(w), 4))
assert loss(2) == 0
print("unseen input:", 2 * 4)
""",
review="در درس بعد روشن می‌کنیم «یادگیری» در این چرخه دقیقاً چه معنایی دارد؛ بعد سراغ متن می‌رویم."),

Lesson("01-learning", 1, "مسئلهٔ یادگیری", "یادگیری ماشین دقیقاً چه کاری می‌کند؟",
"از یک مشاهده تا مجموعه‌داده؛ تفاوت ویژگی، هدف و پارامتر و جای شبکه‌های عصبی در این نقشه.",
"""<p>اگر خودمان بنویسیم «زمان = دو برابر طول»، قانون را برنامه‌نویسی کرده‌ایم. اگر چند ضریب را با داده بسنجیم و ضریب مناسب را انتخاب کنیم، بخشی از قانون را داده تعیین کرده است. <dfn>Machine Learning (یادگیری ماشین)</dfn> ساخت روش‌هایی است که عملکردشان در یک مسئله با استفاده از داده‌ها بهتر می‌شود. «یادگرفتن» اینجا همین معنای عملی را دارد؛ لازم نیست برای برنامه ذهن انسانی فرض کنیم.</p>
<p>اگر قانون دقیق و قابل‌اعتمادی داریم، می‌توانیم آن را مستقیم با Python بنویسیم؛ لازم نیست هر مسئله را به Machine Learning تبدیل کنیم. اما زمان خواندن فقط به تعداد بندها بستگی ندارد: جمله‌ها طول‌های متفاوت دارند و خواننده‌ها هم یکسان نیستند. در چنین مسئله‌ای، نوشتن همهٔ حالت‌ها با <code>if</code> دشوار است. از نمونه‌ها کمک می‌گیریم تا رابطه‌ای تقریبی پیدا کنیم. هنوز باید ورودی، شکل مدل و معیار خطا را انتخاب کنیم و بعد ببینیم نتیجه روی متن تازه هم مفید هست یا نه.</p>
<p><dfn>Dataset (مجموعه‌ای از نمونه‌ها)</dfn> در مثال ما چند متن و زمانِ اندازه‌گیری‌شدهٔ خواندن آن‌هاست. از هر متن، اطلاعاتی را به مدل می‌دهیم: مثلاً تعداد بندها. به هر بخش از این اطلاعات <dfn>Feature (ویژگی ورودی)</dfn> می‌گوییم. اگر میانگین تعداد واژه‌های هر جمله را هم اضافه کنیم، هر نمونه دو Feature دارد. Target چیز دیگری است: زمانی که واقعاً برای خواندن آن متن صرف شده و می‌خواهیم مدل آن را پیش‌بینی کند.</p>
<p>حالا یک متن تازه به مدل بدهید. Featureهایش را می‌توانیم حساب کنیم، اما Target هنوز معلوم نیست؛ قرار است مدل همین پاسخ را حدس بزند. اگر پاسخ را از قبل به ورودی بدهیم، مسئلهٔ پیش‌بینی را دور زده‌ایم. Parameter مثل <code>w</code> هم بخشی از متن نیست؛ متعلق به مدل است. با عوض‌شدن متن، ورودی عوض می‌شود، نه Parameterهای یک مدل آموزش‌دیده.</p>
<p>نوع پاسخ هم مهم است. در <dfn>Regression (پیش‌بینی یک مقدار عددی)</dfn>، اندازهٔ عدد معنا دارد: پیش‌بینی ۴٫۲ دقیقه به هدف ۴ دقیقه نزدیک‌تر از ۹ دقیقه است. در <dfn>Classification (انتخاب میان چند Class)</dfn>، پاسخ یکی از گزینه‌های مشخص است؛ مثلاً موضوع متن «ورزشی» است یا «علمی». هر گزینه را <dfn>Class (یکی از پاسخ‌های ممکن)</dfn> می‌نامیم. شماره‌گذاری Classها ماهیت مسئله را عوض نمی‌کند: اگر برای آن‌ها شناسه‌های ۲ و ۷ بگذاریم، عدد ۴٫۵ یک موضوعِ بینابینی نیست. پیش‌بینی واحد بعدی متن نیز انتخاب میان گزینه‌های مجاز است، نه حدسِ اندازهٔ یک شناسه. به همین دلیل، معیار خطای آن را بعداً متناسب با همین مسئله می‌سازیم.</p>
<p>برای متن «سلام»، اگر ورودی «س» باشد، خود متن می‌گوید پاسخ بعدی «ل» است. پس در مسئلهٔ ادامهٔ متن هم پاسخ مرجع داریم؛ فقط لازم نیست کسی آن را جداگانه برچسب بزند. در <dfn>Supervised learning (یادگیری نظارت‌شده)</dfn>، مدل را با مقایسهٔ پیش‌بینی و پاسخ مرجع آموزش می‌دهیم. <dfn>Self-supervised learning (یادگیری خودنظارتی)</dfn> نام روشی است که این هدف‌ها را از خود داده می‌سازد. بی‌نیازی از برچسب‌گذاری دستی به معنی بی‌نیازی از هدف نیست.</p>
<p><dfn>Neural Network (شبکهٔ عصبی)</dfn> مدلی است که از چند مرحلهٔ محاسبه با پارامترهای قابل یادگیری ساخته می‌شود. «عصبی» نام تاریخی این خانواده است، نه ادعای شباهت کامل به مغز. <dfn>Deep Learning (یادگیری عمیق)</dfn> از شبکه‌های چندلایه برای یادگرفتن نمایش‌ها و رابطه‌های پیچیده استفاده می‌کند. عمق به زنجیرهٔ لایه‌ها اشاره دارد، نه عمقِ فهم انسانی. جزئیات لایه را پس از ریاضی و ابزار خواهیم ساخت.</p>
<p>در مثال زمان خواندن، خودمان تصمیم گرفتیم تعداد بندها را به مدل بدهیم. در مدل زبانی، بخشی از نمایش مفیدِ نشانه‌ها هنگام آموزش یاد گرفته می‌شود؛ بعداً می‌بینیم جدول نمایش نشانه‌ها چطور این کار را انجام می‌دهد. برای شروع، هنوز به شبکه نیاز نداریم. همان انتخاب بهترین ضریب از میان چند گزینه، یک آزمایش کوچک یادگیری است؛ مهم این است که انتخابمان را با داده بسنجیم.</p>""",
"برای سه نمونهٔ زمان خواندن، ویژگی، هدف، پیش‌بینی و پارامتر را جدا بنویسید. سپس جست‌وجوی ساده‌ای بنویسید که بهترین w را از میان ۰، ۰٫۵، ۱، ۱٫۵، ۲ و ۲٫۵ پیدا کند. توضیح دهید چرا x در حلقه تغییر می‌کند ولی پارامتر انتخاب‌شده برای پیش‌بینی بعدی ثابت می‌ماند. در دو مسئلهٔ زمان خواندن و تشخیص موضوع متن، Feature و Target را جدا کنید و بگویید کدام Regression و کدام Classification است. آیا تبدیل نام موضوع‌ها به عدد این پاسخ را عوض می‌کند؟",
"تابع مرجع برای هر ضریب، میانگین مربع خطا را حساب می‌کند و ضریب ۲ را برمی‌گزیند. این هنوز روش کارآمد آموزش مدل بزرگ نیست؛ فقط نشان می‌دهد «انتخاب با داده» چگونه جای حدس دستی را می‌گیرد. برای متن، شناسهٔ نشانه ورودی است و شناسهٔ نشانهٔ بعدی هدف. زمان خواندن Target عددیِ دارای اندازه است؛ موضوع متن یک Class است. شناسهٔ عددی فقط نامِ ذخیره‌شدهٔ Class است و Classification را به Regression تبدیل نمی‌کند.",
"آیا هدفِ خودنظارتی بدون اطلاع از متن ساخته می‌شود؟ با «بابا» دو جفت ورودی و هدف بنویسید.",
"پروژهٔ ما از یک مدل شمارشی شروع می‌شود، سپس به شبکهٔ عصبی می‌رسد. هر دو همان مسئلهٔ پیش‌بینی نشانهٔ بعدی را حل می‌کنند؛ شبکه‌بودن شرط لازم برای مدل‌بودن نیست.",
code="""dataset = [(1, 2), (2, 4), (3, 6)]
candidates = [0, 0.5, 1, 1.5, 2, 2.5]

def mean_squared_error(w):
    return sum((w*x-y)**2 for x, y in dataset) / len(dataset)

best_w = min(candidates, key=mean_squared_error)
assert best_w == 2
print("parameter:", best_w)
print("prediction for feature 4:", best_w * 4)
"""),

Lesson("02-token", 1, "متن به نشانه", "چرا متن را به شناسه تبدیل می‌کنیم؟",
"یک رشتهٔ فارسی را به فهرست عددها و دوباره به همان رشته برگردانیم، بدون اینکه عددها را با معنا اشتباه بگیریم.",
"""<p>پرسش ما ساده است: «پس از م چه می‌آید؟» قبل از شمارش باید تصمیم بگیریم متن را به چه واحدهایی تقسیم کنیم. <dfn>Token (نشانه)</dfn> واحدی است که مدل با آن کار می‌کند. در نسخهٔ نخست هر کاراکتر یک نشانه است؛ فاصله، نیم‌فاصله و علامت سؤال هم سهم خودشان را دارند. «سلام» چهار نشانه دارد، نه یک نشانه.</p>
<p><dfn>Tokenization (نشانه‌بندی)</dfn> تبدیل متن به این واحدهاست. <dfn>Vocabulary (واژگان مدل)</dfn> فهرست واحدهای مجاز و <dfn>Token ID (شناسهٔ نشانه)</dfn> شمارهٔ هر واحد در آن فهرست است. اگر واژگان <code>[' ', 'ا', 'س', 'ل', 'م']</code> باشد، «سلام» به <code>[2,3,1,4]</code> تبدیل می‌شود. شناسه شبیه شمارهٔ خانه است: خانهٔ شمارهٔ ۲۰ الزاماً دو برابر خانهٔ شمارهٔ ۱۰ نیست!</p>
<p><dfn>Encoding (کدگذاری)</dfn> متن را به شناسه‌ها تبدیل می‌کند و <dfn>Decoding (بازگردانی)</dfn> مسیر عکس را می‌رود. برای کاراکترهای شناخته‌شده باید متن اصلی دقیق برگردد. همین آزمون کوچک بعداً مانع چند خطای بزرگ خواهد شد.</p>
<p>رشتهٔ Python دنباله‌ای از Code pointهای <dfn>Unicode (استاندارد شماره‌گذاری کاراکترها)</dfn> است. هر Code point یک شماره در این استاندارد دارد. یک کاراکتر که روی صفحه می‌بینیم همیشه با یک Code point نمایش داده نمی‌شود؛ مثلاً حرف و اعرابش ممکن است جدا ذخیره شوند. Tokenizer فعلی با Code pointهای رشتهٔ Python کار می‌کند، نه لزوماً با واحدهایی که روی صفحه یک کاراکتر به نظر می‌رسند.</p>
<p>واژگان را با <code>sorted(set(text))</code> می‌سازیم: حذف تکرار، سپس ترتیب ثابت. ترتیب یک set قرارداد واژگان نیست. اگر امروز «س» شناسهٔ ۲ و فردا شناسهٔ ۴ بگیرد، عددهایی که مدل برایش آموخته به نشانهٔ دیگری وصل می‌شوند. برای این نگاشت، آزمون رفت‌وبرگشت نشان می‌دهد که هر شناسه دوباره به همان کاراکتر برمی‌گردد.</p>""",
"encode و decode را با یک دیکشنری و یک فهرست بنویسید. «سلام hello!» را رفت‌وبرگشت دهید. پیش از امتحان‌کردن «ژ»، بگویید برنامهٔ ساده چه خطایی می‌دهد؛ فعلاً آن خطا را پنهان نکنید.",
"دیکشنری، کاراکتر را به شناسه و فهرست، شناسه را به کاراکتر می‌برد. assert باید برای متن شناخته‌شده برقرار باشد. ژ در واژگان مثال نیست؛ encode ساده برای آن KeyError می‌دهد. رفتار کاراکترِ ندیده را در بخش چهار با قراردادی صریح طراحی می‌کنیم.",
"اگر دو شناسه را در کدگذاری جابه‌جا کنید اما جدول بازگردانی را تغییر ندهید، چه می‌شود؟ با دو حرف نشان دهید.",
"این نگاشت نخستین قطعهٔ پروژه است. نسخهٔ فعلی را خودتان بنویسید؛ فایل tokenizer.py نسخهٔ گسترش‌یافته با اعتبارسنجی و ذخیره‌سازی است، نه پیش‌نیاز این درس.",
code="""text = "سلام hello!"
vocabulary = sorted(set(text))
to_id = {char: index for index, char in enumerate(vocabulary)}

def encode(value):
    return [to_id[char] for char in value]

def decode(ids):
    return "".join(vocabulary[index] for index in ids)

ids = encode(text)
assert decode(ids) == text
assert "ژ" not in to_id
print(vocabulary, ids, decode(ids), sep="\\n")
""", source="mini_gpt/tokenizer.py"),

Lesson("03-counts", 1, "اولین ادامه‌دهنده", "نسخهٔ صفر: آیا شمارش می‌تواند متن بسازد؟",
"با یک جدول کوچک، نشانهٔ بعدی را انتخاب کنیم؛ بعد ببینیم این حافظهٔ کوتاه چه چیزهایی را از دست می‌دهد.",
"""<p>در «بابا»، پس از «ب» دو بار «ا» و پس از «ا» یک بار «ب» آمده است. <dfn>Bigram (جفت نشانهٔ مجاور)</dfn> نام چنین زوجی است. اگر برای هر نشانه، تعدادِ نشانه‌های بعدی را نگه داریم، یک مدل سادهٔ ادامهٔ متن ساخته‌ایم. عددهای این مدل شمارش‌اند، نه وزن‌های یک شبکهٔ عصبی.</p>
<p><dfn>Context (زمینهٔ در دسترس)</dfn> بخش ورودی است که تصمیم به آن وابسته است. زمینهٔ این مدل فقط آخرین نشانه است. «سلام» و «قلم» چون هر دو به «م» ختم می‌شوند، جدول ادامهٔ یکسانی دارند. برنامه تنبل نشده؛ ما حافظهٔ بیشتری به آن نداده‌ایم.</p>
<p>برای تولید می‌توان همیشه پرتکرارترین ادامه را گرفت، یا به گزینه‌های پرتکرار شانس بیشتری داد. <dfn>Sampling (نمونه‌گیری)</dfn> یعنی انتخاب تصادفی با وزن‌های مشخص. در مثال «بابا» اگر واژگان فقط ب و ا باشد، پس از ب شمارش‌ها ۰ و ۲ هستند. با افزودن یک به هر شمارش، وزن‌ها ۱ و ۳ می‌شوند؛ شانس انتخاب ب یک‌چهارم و ا سه‌چهارم است.</p>
<p>این افزودن یک را <dfn>Add-one smoothing (هموارسازی با افزودن یک)</dfn> می‌نامند. راهی ساده برای صفرنشدن شانس گزینهٔ ندیده است، نه یک حقیقت دربارهٔ زبان. در واژگان بزرگ، همین یک‌های ظاهراً کوچک می‌توانند اثر زیادی داشته باشند.</p>
<p><code>random.choices</code> در کتابخانهٔ استاندارد Python گزینه‌ها و وزنشان را می‌گیرد. با <code>random.Random(42)</code> یک مولد تصادف مستقل می‌سازیم. <dfn>Seed (بذر تصادفی)</dfn> مقدار آغاز این مولد است؛ ثابت‌بودن آن در محیط یکسان، مقایسه را تکرارپذیر می‌کند. بذر خوب، جای دادهٔ خوب را نمی‌گیرد.</p>""",
"جدول «بابا» را روی کاغذ بسازید. یک ادامه‌دهنده بنویسید که در هر گام فقط آخرین کاراکتر را ببیند. سپس نسخهٔ صفر پروژه را اجرا کنید و پنج خروجی را از نظر تکه‌های آشنا و جمله‌های نامنسجم مقایسه کنید.",
"ب→ا دو بار و ا→ب یک بار دیده شده‌اند. شمارش مرجع این قرارداد را می‌آزماید. خروجی تصادفی پاسخ یکتایی ندارد؛ معیار درست، انتخاب طبق جدول و محدودماندن زمینه به آخرین نشانه است. آشنا به‌نظررسیدن چند تکه شاهد فهم زبان نیست.",
"چرا تغییر ابتدای جمله، وقتی آخرین نشانه ثابت است، توزیع ادامهٔ این مدل را عوض نمی‌کند؟",
"این همان v0 اجرایی پروژه است. آن را با python -m mini_gpt.stages.v0 از ریشهٔ پروژه اجرا کنید؛ در مراحل بعد مسئله را حفظ می‌کنیم و حافظه و نمایش مدل را گسترش می‌دهیم.",
code="""from collections import Counter, defaultdict
import random

text = "بابا"
counts = defaultdict(Counter)
for current, following in zip(text, text[1:]):
    counts[current][following] += 1
assert counts["ب"]["ا"] == 2
assert counts["ا"]["ب"] == 1

vocabulary = sorted(set(text))
rng = random.Random(42)
output = "ب"
for _ in range(12):
    weights = [counts[output[-1]][char] + 1 for char in vocabulary]
    output += rng.choices(vocabulary, weights=weights, k=1)[0]
print(output)
""", source="mini_gpt/stages/v0.py",
review="پیش از عوض‌کردن مدل، یک محدودیت مشخصش را در دفتر آزمایش بنویسید؛ «خروجی بد است» هنوز توضیح نیست."),

Lesson("04-splits", 1, "شواهد یادگیری", "چرا متن ندیده را کنار می‌گذاریم؟",
"میان حفظ‌کردن نمونه‌ها و یادگرفتن رابطه‌ای قابل استفاده فرق بگذاریم.",
"""<p>فرض کنید جدول شمارش را از یک متن ساخته‌ایم و حالا مدل را با ادامه‌دادن همان متن می‌سنجیم. آشنا بودن خروجی تعجبی ندارد: مدل پیش‌تر همین جفت‌ها را شمرده است. این آزمایش هنوز نمی‌گوید روی متن تازه چه می‌کند. برای پاسخ به آن پرسش، باید بخشی از داده را از فرایند تنظیم مدل کنار بگذاریم.</p>
<p><dfn>Training set (دادهٔ آموزش)</dfn> برای تغییر پارامترهای مدل است. <dfn>Validation set (دادهٔ کنارگذاشته‌شده برای انتخاب تنظیمات)</dfn> برای انتخاب تنظیمات و تشخیص مشکل استفاده می‌شود. <dfn>Test set (دادهٔ آزمون نهایی)</dfn> پس از پایان این تصمیم‌ها، برآورد نهایی می‌دهد. اگر بارها با دیدن نتیجهٔ آزمون تنظیمات را عوض کنیم، آن بخش در عمل به اعتبارسنجی تبدیل شده است.</p>
<p><dfn>Generalization (تعمیم)</dfn> یعنی رابطهٔ آموخته‌شده روی نمونه‌های تازه نیز مفید باشد. <dfn>Overfitting (بیش‌برازش)</dfn> زمانی است که مدل بیش از اندازه با جزئیات آموزش سازگار می‌شود و این بهبود به دادهٔ تازه منتقل نمی‌شود. <dfn>Underfitting (کم‌برازش)</dfn> یعنی حتی رابطهٔ لازم در دادهٔ آموزش نیز خوب آموخته نشده؛ مدل خیلی محدود یا آموزش ناکافی دو علت ممکن‌اند، نه تنها علت‌ها.</p>
<p><dfn>Data leakage (نشت داده)</dfn> ورود اطلاعاتی به فرایند یادگیری یا تصمیم‌گیری است که طبق قرارداد آزمایش باید مستقل بماند. در پروژه ابتدا متن را به بخش آموزش و اعتبارسنجی می‌بریم و سپس واژگان و جدول‌ها را فقط از آموزش می‌سازیم. نمونه‌ای هم از دو سوی مرز برنمی‌داریم.</p>
<p>جداکردن دو برش از متن کافی نیست که آن‌ها را مستقل بدانیم. ممکن است نسخهٔ تکراری یک سند در هر دو بخش باشد، یا پایان متن همان موضوع و منبع آغاز آن را داشته باشد. در دادهٔ واقعی باید سندها را جدا کنیم و دنبال تکرارها بگردیم؛ صرفاً کشیدن یک مرز میان دو برش این مشکل را حل نمی‌کند.</p>
<p>دادهٔ نمونهٔ Mini-GPT آزمون نهایی مستقلی همراه ندارد. در درس ارزیابی نهایی، فایل Test مستقل خودتان را معرفی می‌کنید. تا آن زمان، عدد اعتبارسنجی را در محدودهٔ همین داده تفسیر کنید؛ از آن نمی‌توان دربارهٔ کیفیت عمومی زبان مدل نتیجه گرفت.</p>""",
"ده سطر متن بسازید. هشت سطر را برای شمارش و دو سطر را فقط برای بررسی نگه دارید. سپس عمداً یک سطر آموزش را در قسمت کنارگذاشته‌شده تکرار کنید و بنویسید کدام ادعای آزمایش ضعیف شده است.",
"باید بتوانید نشان دهید تابع ساخت واژگان و شمارش فقط بخش آموزش را دریافت کرده است. تکرارِ سند میان بخش‌ها این مرز ظاهری را بی‌اثر می‌کند؛ متفاوت‌بودن نام متغیرها، مستقل‌بودن داده را ثابت نمی‌کند.",
"اگر خطای آموزش زیاد باشد، آیا فوراً می‌توان گفت مدل بیش‌برازش دارد؟ تفاوت دو وضعیت را با یک مثال توضیح دهید.",
"data.py همین جداسازی پیش از ساخت واژگان را انجام می‌دهد. فعلاً مرز اطلاعات را درست بگذارید؛ محاسبهٔ عددی اعتبارسنجی را پس از ساخت شبکه اضافه می‌کنیم.",
code="""lines = [f"نمونهٔ شمارهٔ {number}" for number in range(10)]
train_lines = lines[:8]
validation_lines = lines[8:]
train_text = "\\n".join(train_lines)
validation_text = "\\n".join(validation_lines)
vocabulary = sorted(set(train_text))
assert len(train_lines) == 8 and len(validation_lines) == 2
assert set(train_lines).isdisjoint(validation_lines)
print("unseen characters:", sorted(set(validation_text) - set(vocabulary)))
""",
review="یک روز بعد، بدون بازکردن درس تفاوت آموزش، اعتبارسنجی و آزمون نهایی را بنویسید. یک مثال نشت هم از پروژهٔ خودتان پیدا کنید."),
]
